package com.inventario.service;
import com.inventario.domain.*; import com.inventario.dto.Dtos.*; import com.inventario.exception.ApiException; import com.inventario.repository.*; import org.springframework.stereotype.Service; import java.util.List;
@Service public class ProductoService { private final ProductoRepository repo; public ProductoService(ProductoRepository repo){this.repo=repo;} public List<Producto> listar(){return repo.findAll();} public List<Producto> catalogo(){return repo.findByActivoTrue();} public Producto crear(ProductoRequest r){if(r.precio()==null||r.precio().signum()<0||r.stock()==null||r.stock()<0)throw new ApiException("Precio y stock válidos son obligatorios");Producto p=new Producto();p.setNombre(r.nombre());p.setDescripcion(r.descripcion());p.setPrecio(r.precio());p.setStock(r.stock());p.setActivo(r.activo()==null||r.activo());return repo.save(p);} public Producto actualizar(Long id,ProductoRequest r){Producto p=repo.findById(id).orElseThrow(()->new ApiException("Producto no encontrado"));p.setNombre(r.nombre());p.setDescripcion(r.descripcion());p.setPrecio(r.precio());p.setStock(r.stock());p.setActivo(r.activo());return repo.save(p);} public void eliminar(Long id){repo.deleteById(id);} }
